from deprecation import deprecated
from nokia_nom_open_api_client import (Ne3sParameterBulkUploadOperationStartObject, BulkUploadRequestV2,
                                       Ne3sPlanProvOperationStartObject, ProvisionRequestV2,
                                       GenericPlanProvisionRequestV1Operations)
from ..utils import log_trigger_operation_data


class Deprecated(object):
    def __init__(self, api_client):
        """
        :param DeprecatedApi api_client:
        """
        self.api_client = api_client

    @deprecated(details='Please use upload_parameter instead.')
    @log_trigger_operation_data
    def bulk_upload_parameter(self, integrated_ids):
        ne3s_parameter_bulk_upload_operation_start_object = Ne3sParameterBulkUploadOperationStartObject(
            operation_attributes=BulkUploadRequestV2(integrated_element_ids=integrated_ids)
        )
        return self.api_client.api_operations_v1_request_start_parameter_bulk_upload_post(
            ne3s_parameter_bulk_upload_operation_start_object)

    @deprecated(details='Please use upload_parameter instead.')
    @log_trigger_operation_data
    def bulk_upload_ne3s_parameter(self, integrated_ids):
        ne3s_parameter_bulk_upload_operation_start_object = Ne3sParameterBulkUploadOperationStartObject(
            operation_attributes=BulkUploadRequestV2(integrated_element_ids=integrated_ids)
        )
        return self.api_client.api_operations_v1_request_start_ne3s_parameter_bulk_upload_post(
            ne3s_parameter_bulk_upload_operation_start_object)

    @log_trigger_operation_data
    def provision_plan_for_ne3s_elements(self, plan_name, download, validation, activation,
                                         rollback_plan_generation=False):
        ne3s_plan_prov_operation_start_object = Ne3sPlanProvOperationStartObject(
            operation_attributes=ProvisionRequestV2(
                plan_name=plan_name,
                operations=GenericPlanProvisionRequestV1Operations(
                    download=download,
                    validation=validation,
                    activation=activation,
                    rollback_plan_generation=rollback_plan_generation
                )
            )
        )
        return self.api_client.api_operations_v1_request_start_ne3s_plan_provision_post(
            ne3s_plan_prov_operation_start_object=ne3s_plan_prov_operation_start_object)

    def download_plan(self, plan_name):
        return self.provision_plan_for_ne3s_elements(
            plan_name=plan_name, download=True, validation=False, activation=False)

    def validate_plan(self, plan_name):
        return self.provision_plan_for_ne3s_elements(
            plan_name=plan_name, download=False, validation=True, activation=False)

    def activate_plan(self, plan_name):
        return self.provision_plan_for_ne3s_elements(
            plan_name=plan_name, download=False, validation=False, activation=True)

    def provision_plan(self, plan_name, rollback_plan_generation):
        return self.provision_plan_for_ne3s_elements(
            plan_name=plan_name, download=True, validation=True, activation=True,
            rollback_plan_generation=rollback_plan_generation)
